body.script:
(function(){
  /* 反馈类型单选切换 */
  var chips=document.querySelectorAll('.chips-row .chip');
  chips.forEach(function(c){
    c.addEventListener('click',function(){
      chips.forEach(function(x){x.classList.remove('chip-active')});
      c.classList.add('chip-active');
    });
  });
  /* 字数统计 */
  var ta=document.querySelector('[data-dom-id="feedback-desc"]');
  var ct=document.querySelector('[data-dom-id="desc-count"]');
  if(ta&&ct){
    ta.addEventListener('input',function(){ct.textContent=ta.value.length});
  }
})();
